import { useCallback, useEffect, useRef, useState } from 'react';
import { Search, MapPin, Radius, Loader2, Globe2, X } from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { usePersistedState } from '@/hooks/usePersistedState';
import logoIcon from '@/assets/leadfinder-logo-icon.png';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Slider } from '@/components/ui/slider';
import { Switch } from '@/components/ui/switch';
import { Card, CardContent } from '@/components/ui/card';
import { SuggestedLocations } from '@/components/SuggestedLocations';
import { Select, SelectContent, SelectGroup, SelectItem, SelectLabel, SelectSeparator, SelectTrigger, SelectValue } from '@/components/ui/select';
import { SEARCH_COUNTRY_OPTIONS, countryName, locationAfterCountryChange, normaliseSearchCountry, quickLocationValue } from '@/lib/locationPicker';
import { QuickBusinessTypes } from '@/components/QuickBusinessTypes';
import type { Country } from '@/types/lead';
import type { SearchFilters } from '@/types/lead';
import { MANY_TOWNS_MAX_PER_PRESS, parseTownList, townsForPress } from '@/lib/manyTowns';

interface SearchFormProps {
  onSearch: (filters: SearchFilters) => void;
  isLoading: boolean;
  isOnTrial?: boolean;
  searchesRemaining?: number;
  dailyLimit?: number;
  isPaidSubscriber?: boolean;
  disabled?: boolean;
  initialRadius?: number;
  /* URL-SEEDED VALUES. Present when the page was opened from Coverage's "Find leads", or on a
     pasted link / refresh / back button. They win over the persisted boxes ONCE, on mount, so the
     inputs describe the search actually on screen — boxes reading "plumber / Bourne" above Wisbech
     locksmiths results is the quiet kind of wrong this codebase keeps getting caught by. */
  initialKeyword?: string;
  initialLocation?: string;
  /** The country to search in, from Coverage's Find leads (2026-10-14) — seeded like the keyword and town. */
  initialCountry?: Country;
  /**
   * Run the search ONCE on arrival — set by Coverage's "Find leads" button, which exists to run a
   * search rather than to prefill a box and wait.
   *
   * ⚠️ IT USED TO BE A MODE RATHER THAN A BOOLEAN, and that mattered while this form could also run
   * a market view: `mode` was persisted, so an operator whose last visit was a market view would
   * have fired a MARKET VIEW from a button labelled Find leads. The market view is gone
   * (2026-09-09), so there is only one thing to run and the mode guard has nothing left to protect.
   * ⛔ THE GUARD THAT STILL MATTERS IS BELOW AND IS UNCHANGED: keyword and location are PERSISTED,
   * so this must not fire until the form actually HOLDS what the URL asked for. Firing early runs
   * the PREVIOUS search's terms, spends the money, and then paints the right town above the wrong
   * results.
   */
  autoSubmit?: boolean;
  /* ══ MANY TOWNS (2026-10-16, V2's "Many towns" mode; src/lib/manyTowns.ts) ══════════════════════════════════
     Present = the form offers "One town | Many towns". In Many towns the location box becomes a town list; the press
     hands the page the SAME trade / country / radius the one-town search sends, with "this town only" on (each town
     searched as itself, never a radius around it). */
  many?: boolean;
  onManyChange?: (many: boolean) => void;
  pickedTowns?: string[];
  onPickedTownsChange?: (towns: string[]) => void;
  onSearchMany?: (base: Omit<SearchFilters, 'location'>) => void;
  onUpgrade?: () => void;
  isUpgradeLoading?: boolean;
  freeSearchesExhausted?: boolean;
}

export function SearchForm({ 
  onSearch, 
  isLoading, 
  isOnTrial = false, 
  searchesRemaining = 2, 
  dailyLimit = 2,
  isPaidSubscriber = false,
  disabled = false,
  initialRadius,
  initialKeyword,
  initialLocation,
  initialCountry,
  autoSubmit = null,
  many = false,
  onManyChange,
  pickedTowns = [],
  onPickedTownsChange,
  onSearchMany,
  onUpgrade,
  isUpgradeLoading = false,
  freeSearchesExhausted = false,
}: SearchFormProps) {
  // Persist the search inputs per-user (tier 'both' to survive a tab close, matching the
  // already-persisted results) so returning to Find Leads keeps the boxes filled.
  const { user } = useAuth();
  const persist = { tier: 'both', scope: user?.id } as const;
  const [keyword, setKeyword] = usePersistedState('find-leads-keyword', '', persist);
  const [location, setLocation] = usePersistedState('find-leads-location', '', persist);
  const [radius, setRadius] = usePersistedState('find-leads-radius', initialRadius ?? 50, persist);
  const [storedCountry, setSelectedCountry] = usePersistedState<Country>('find-leads-country', 'UK' as Country, persist);
  /* An old or hand-edited stored value is read as the default, never sent to the search as a bias. */
  const selectedCountry = normaliseSearchCountry(storedCountry);
  /* COUNTRY → LOCATION → RADIUS. A new country clears a Location that belonged to the old one (one of its
     suggestions, or text naming it) and keeps one the person typed that names no country; the radius and
     "This town only" are never touched (src/lib/locationPicker.ts). */
  const changeCountry = (next: Country) => {
    if (next === selectedCountry) return;
    setLocation(locationAfterCountryChange(location, selectedCountry, next));
    setSelectedCountry(next);
  };
  const primaryCountries = SEARCH_COUNTRY_OPTIONS.filter((o) => o.primary);
  const otherCountries = SEARCH_COUNTRY_OPTIONS.filter((o) => !o.primary);
  // Persisted exactly like radius — same tier, same per-user scope — so the mode survives a
  // reload instead of quietly reverting to a radius search between sessions.
  /* ⛔ DEFAULT ON, 2026-08-09. locationBias is a HINT — Google returns results outside the circle
     whatever the radius — so the old default let a Corby locksmith arrive from a Wisbech search and
     be audited against Wisbech. 31 of 44 measurable audits were more than 10km from the town they
     asked about; 28 of those reached a prospect.
     ⚠️ IT DOES NOT LOSE LEADS. townOnly runs a nearby pass and returns out-of-boundary results
     ALONGSIDE the town ones, tagged outsideTown, now rendered as an "Outside town" badge. Measured
     against Google's own cached viewports: 63% of leads with coordinates sit outside the town they
     were searched from — 91% for Wisbech, 92% for Bourne. Those are the leads that were quietly
     becoming wrong-town audits; they are still returned, just no longer indistinguishable.
     ⚠️ IT COSTS ONE EXTRA GOOGLE PAGE per search (~$0.035) for the nearby pass. A persisted toggle,
     so turning it off once turns it off for good. */
  const [townOnly, setTownOnly] = usePersistedState('find-leads-town-only', true, persist);
  /* ⚠️ `find-leads-mode` IS NO LONGER READ. It was the persisted leads/market choice; the market
     view was removed on 2026-09-09. Old values stay in browser storage harmlessly — nothing reads
     the key, and clearing other people's localStorage is not worth a migration. */

  /* Apply the URL seeds once. Ref-guarded rather than an empty dep array so the linter stays happy
     and a later re-render can never re-stomp what the operator has since typed. */
  const seeded = useRef(false);
  useEffect(() => {
    if (seeded.current) return;
    seeded.current = true;
    if (initialKeyword) setKeyword(initialKeyword);
    if (initialLocation) setLocation(initialLocation);
    if (initialCountry) setSelectedCountry(initialCountry);
  }, [initialKeyword, initialLocation, initialCountry, setKeyword, setLocation, setSelectedCountry]);

  /* ⛔ ONE PLACE BUILDS THE FILTERS, so the auto-run and the button cannot send different searches.
     Every value comes from the form's own state — the radius, country and town-only the operator can
     SEE — rather than from defaults invented by whoever triggered it. A search that ran on 50km while
     the box read 25km is the "measurement right, document lying" fault in its cheapest form. */
  const runSearch = useCallback(() => {
    if (!keyword.trim() || !location.trim()) return false;
    onSearch({
      keyword: keyword.trim(),
      location: location.trim(),
      // Still sent when townOnly is on: the server ignores it for the search itself but uses it
      // for the cache key and for the fallback message if the town has no boundary.
      radius: radius * 1000,
      country: selectedCountry,
      townOnly,
    });
    return true;
  }, [keyword, location, radius, selectedCountry, townOnly, onSearch]);

  /* MANY TOWNS: the one-town filters minus the town — the same trade words, country and radius, "this town only" on. */
  const runMany = useCallback(() => {
    if (!keyword.trim() || !pickedTowns.length || !onSearchMany) return false;
    onSearchMany({ keyword: keyword.trim(), radius: radius * 1000, country: selectedCountry, townOnly: true });
    return true;
  }, [keyword, pickedTowns.length, onSearchMany, radius, selectedCountry]);
  const [townInput, setTownInput] = useState('');
  const addTowns = (raw: string) => {
    const next = parseTownList([...pickedTowns, ...raw.split(/[,|\n]+/)]);
    onPickedTownsChange?.(next);
  };
  const press = townsForPress(pickedTowns);
  /* No template inside a template (CLAUDE.md): the note is built from plain pieces. */
  const manyNote = pickedTowns.length === 0 ? 'Pick towns, or tick them on Coverage.'
    : 'Each town is searched on its own, exactly like a one-town search, up to ' + MANY_TOWNS_MAX_PER_PRESS + ' per press.'
      + (press.later.length ? ' ' + press.later.length + ' more stay selected for the next press.' : '');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (many) runMany();
    else runSearch();
  };

  /* THE ARRIVAL RUN, AND EVERY CONDITION ON IT IS A POSITIVE TEST OF WHAT WE WANT.
     ⛔ THE BUG THIS SHAPE EXISTS TO PREVENT, caught before shipping: keyword and location are
     PERSISTED, and the seeding effect above sets state — which is not visible until the next render.
     On the first commit this effect still sees the PREVIOUS search's values. Firing then would run
     "plumber / Bourne" from a button that said locksmiths in Wisbech, spend the money, and then paint
     the right town in the boxes above the wrong results. Exactly the measurement-right /
     document-lying fault, in its cheapest form.
     So it fires only when the form HOLDS WHAT THE URL ASKED FOR — same keyword, same town. A seed
     that has not landed yet, or failed to land at all, spends nothing and leaves the operator to
     press Search. */
  const autoSubmitted = useRef(false);
  useEffect(() => {
    if (!autoSubmit || autoSubmitted.current || !seeded.current) return;
    if (initialKeyword && keyword.trim() !== initialKeyword.trim()) return;   // the trade we were asked for
    if (initialLocation && location.trim() !== initialLocation.trim()) return; // the town we were asked for
    if (initialCountry && selectedCountry !== initialCountry) return;          // the country we were asked for
    if (!keyword.trim() || !location.trim()) return;                       // nothing to search for
    autoSubmitted.current = true;
    runSearch();
  }, [autoSubmit, keyword, location, initialKeyword, initialLocation, initialCountry, selectedCountry, runSearch]);

  return (
    <Card className="border-border/50 bg-card shadow-sm">
      <CardContent className="p-3 sm:p-6">
        <form onSubmit={handleSubmit} className="space-y-3 sm:space-y-6">
          {/* ⛔ THE MODE TOGGLE IS GONE (2026-09-09). This form used to offer "Find leads" or
              "Market view", and the second is what Paul said he never uses — confirmed against the
              data: 96 market audits ever, ALL in August, none since the 24th, while 1,352 leads were
              added by plain search in the same fortnight. The question the market view was built to
              answer ("is this niche worth outreaching?") is answered better and for free by the
              trade-wide niche read on Coverage, so there is one thing this form does now and it
              does not need naming twice. */}
          <div className="flex flex-wrap items-center justify-between gap-2">
            <p className="text-[11px] text-muted-foreground">
              Search returns local businesses you can add to the CRM.
            </p>
            {onManyChange && (
              <div className="inline-flex rounded-full border border-border bg-muted/40 p-0.5 text-xs font-medium" role="group" aria-label="Search one town or many" data-testid="town-mode">
                {([[false, 'One town'], [true, 'Many towns']] as const).map(([m, label]) => (
                  <button key={label} type="button" aria-pressed={many === m} onClick={() => onManyChange(m)}
                    className={`rounded-full px-3 py-1 transition-colors ${many === m ? 'bg-primary text-primary-foreground' : 'text-foreground/80 hover:text-primary'}`}>{label}</button>
                ))}
              </div>
            )}
          </div>

          {/* Main Search Fields */}
          <div className="grid gap-3 sm:gap-4 sm:grid-cols-2 lg:grid-cols-12">
            <div className="min-w-0 space-y-1.5 sm:space-y-2 lg:col-span-4" data-walkthrough-step="business-type-area">
              <Label htmlFor="keyword" className="text-xs font-medium text-foreground/80">
                Business Type
              </Label>
              <div className="relative">
                <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 sm:h-4 sm:w-4 text-muted-foreground" />
                <Input
                  id="keyword"
                  placeholder="e.g. plumber, electrician"
                  value={keyword}
                  onChange={(e) => setKeyword(e.target.value)}
                  className="pl-8 sm:pl-10 h-9 sm:h-10 bg-input border-border focus:ring-primary text-sm"
                  data-walkthrough-step="business-type"
                />
              </div>
              <QuickBusinessTypes onSelect={setKeyword} selected={keyword} />
            </div>

            <div className="min-w-0 space-y-3 lg:col-span-5" data-walkthrough-step="location-area">
              {/* ⛔ COUNTRY → LOCATION → RADIUS (2026-10-07, src/lib/locationPicker.ts). The country is a normal
                  dropdown showing its NAME (no flag emoji — Windows draws those as "GB"), then the location, then
                  this country's suggestions. It is SHOWN, never remembered out of sight (2026-09-28: a hidden
                  choice stored 349 UK businesses as USA), and it only BIASES the search — the leads carry the
                  country Google resolved (leadCountry.ts). */}
              <div className="space-y-1.5">
                <Label htmlFor="find-leads-country" className="text-xs font-medium text-foreground/80">
                  Country
                </Label>
                <Select value={selectedCountry} onValueChange={(v) => changeCountry(normaliseSearchCountry(v))}>
                  <SelectTrigger id="find-leads-country" className="h-9 sm:h-10 bg-input border-border text-sm" aria-label="Country" data-testid="find-leads-country">
                    <span className="flex min-w-0 items-center gap-2">
                      <Globe2 className="h-3.5 w-3.5 sm:h-4 sm:w-4 shrink-0 text-muted-foreground" />
                      <SelectValue />
                    </span>
                  </SelectTrigger>
                  <SelectContent className="max-h-80">
                    <SelectGroup>
                      <SelectLabel className="text-[11px] text-muted-foreground">Main markets</SelectLabel>
                      {primaryCountries.map((c) => (
                        <SelectItem key={c.value} value={c.value} className="text-sm">
                          {c.name}<span className="ml-2 text-[10px] font-medium text-muted-foreground">{c.code}</span>
                        </SelectItem>
                      ))}
                    </SelectGroup>
                    <SelectSeparator />
                    <SelectGroup>
                      <SelectLabel className="text-[11px] text-muted-foreground">Other countries</SelectLabel>
                      {otherCountries.map((c) => (
                        <SelectItem key={c.value} value={c.value} className="text-sm">
                          {c.name}<span className="ml-2 text-[10px] font-medium text-muted-foreground">{c.code}</span>
                        </SelectItem>
                      ))}
                    </SelectGroup>
                  </SelectContent>
                </Select>
              </div>
              {!many ? (<>
              <div className="space-y-1.5">
                <Label htmlFor="location" className="text-xs font-medium text-foreground/80">
                  Location
                </Label>
                <div className="relative">
                  <MapPin className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 sm:h-4 sm:w-4 text-muted-foreground" />
                  <Input
                    id="location"
                    placeholder="Town, suburb or postcode"
                    value={location}
                    onChange={(e) => setLocation(e.target.value)}
                    className="pl-8 sm:pl-10 h-9 sm:h-10 bg-input border-border focus:ring-primary text-sm"
                    data-walkthrough-step="location"
                    aria-describedby="find-leads-location-hint"
                  />
                </div>
                <p id="find-leads-location-hint" className="sr-only">Searching in {countryName(selectedCountry)}</p>
              </div>
              <SuggestedLocations
                country={selectedCountry}
                location={location}
                onPick={(city) => setLocation(quickLocationValue(city, selectedCountry))}
              />
              </>) : (
                <div className="space-y-1.5" data-testid="many-towns-picker">
                  <Label htmlFor="many-town-input" className="text-xs font-medium text-foreground/80">Towns</Label>
                  {pickedTowns.length > 0 && (
                    <div className="flex flex-wrap gap-1.5" data-testid="many-towns-picked">
                      {pickedTowns.map((t, i) => (
                        <span key={t} className={`inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-xs ring-1 ring-inset ${i < MANY_TOWNS_MAX_PER_PRESS ? 'bg-primary/10 text-foreground ring-primary/40' : 'bg-muted text-muted-foreground ring-border'}`}>
                          {t}
                          <button type="button" aria-label={`Remove ${t}`} onClick={() => onPickedTownsChange?.(pickedTowns.filter((x) => x !== t))}><X className="h-3 w-3" /></button>
                        </span>
                      ))}
                    </div>
                  )}
                  <div className="flex gap-2">
                    <div className="relative min-w-0 flex-1">
                      <MapPin className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 sm:h-4 sm:w-4 text-muted-foreground" />
                      <Input id="many-town-input" placeholder="Add a town (or several, with commas)" value={townInput}
                        onChange={(e) => setTownInput(e.target.value)}
                        onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); if (townInput.trim()) { addTowns(townInput); setTownInput(''); } } }}
                        className="pl-8 sm:pl-10 h-9 sm:h-10 bg-input border-border focus:ring-primary text-sm" />
                    </div>
                    <Button type="button" variant="outline" className="h-9 sm:h-10" disabled={!townInput.trim()} onClick={() => { addTowns(townInput); setTownInput(''); }}>Add</Button>
                  </div>
                  <p className="text-[11px] text-muted-foreground" data-testid="many-towns-note">
                    {manyNote}
                  </p>
                  <SuggestedLocations country={selectedCountry} location="" onPick={(city) => addTowns(quickLocationValue(city, selectedCountry))} />
                </div>
              )}
            </div>

            {/* HOW WIDE TO SEARCH — one control group. The radius and the town boundary answer the
                same question, so they share a cell. As its own bordered block below the grid the
                toggle read as an unrelated setting. */}
            <div className="min-w-0 space-y-1.5 sm:space-y-2 sm:col-span-2 lg:col-span-3">
              <div className="flex items-center justify-between gap-3">
                <Label className={`whitespace-nowrap text-xs font-medium transition-colors ${townOnly || many ? 'text-muted-foreground/50' : 'text-foreground/80'}`}>
                  Radius: {radius} km
                </Label>
                {many ? <span className="text-xs font-medium text-foreground/80" data-testid="many-towns-town-only">Each town only</span> : <div className="flex items-center gap-2">
                  <Label
                    htmlFor="town-only"
                    className="whitespace-nowrap text-xs font-medium cursor-pointer text-foreground/80"
                  >
                    This town only
                  </Label>
                  <Switch
                    id="town-only"
                    checked={townOnly}
                    onCheckedChange={setTownOnly}
                  />
                </div>}
              </div>
              {/* Dimmed as ONE unit — icon, track and thumb together — so "off" reads as deliberate
                  rather than broken. The shared Slider's own `disabled:opacity-50` sits on the thumb
                  and never fires: Radix sets data-disabled, not the HTML disabled attribute, so
                  without this the control looks live while ignoring every drag. `disabled` stays for
                  the real a11y/interaction state; the opacity is only what makes it legible. */}
              <div className={`relative flex items-center gap-2 sm:gap-3 pt-0.5 transition-opacity ${townOnly || many ? 'opacity-40' : ''}`}>
                <Radius className="h-3.5 w-3.5 sm:h-4 sm:w-4 flex-shrink-0 text-muted-foreground" />
                <Slider
                  value={[radius]}
                  onValueChange={(value) => setRadius(value[0])}
                  min={1}
                  max={50}
                  step={1}
                  disabled={townOnly || many}
                  className="flex-1"
                />
              </div>
            </div>
          </div>

          {/* Submit Button with Trial Indicator */}
          <div className="flex flex-col sm:flex-row items-center justify-end gap-3 sm:gap-4">
            <div className="flex flex-col items-center sm:items-end w-full sm:w-auto">
              {freeSearchesExhausted && !isPaidSubscriber ? (
                /* Exhausted state: disabled search + upgrade CTA */
                <div className="w-full space-y-3">
                  <Button
                    type="button"
                    size="lg"
                    className="btn-premium w-full sm:w-auto gap-2 font-semibold px-5 sm:px-8 h-[44px] sm:h-[44px] text-sm text-white"
                    disabled={isUpgradeLoading}
                    onClick={onUpgrade}
                  >
                    {isUpgradeLoading ? (
                      <><Loader2 className="h-3.5 w-3.5 animate-spin" />Starting...</>
                    ) : (
                      <><img src={logoIcon} alt="" className="h-5 w-5 object-contain" />Upgrade to Unlock</>
                    )}
                  </Button>
                </div>
              ) : (
                <>
                  <Button 
                    type="submit" 
                    disabled={isLoading || !keyword.trim() || (many ? pickedTowns.length === 0 : !location.trim()) || disabled}
                    className="bg-primary hover:bg-primary/90 text-primary-foreground font-semibold px-5 sm:px-8 h-[44px] sm:h-[44px] py-2 w-full sm:w-auto text-sm"
                    data-walkthrough-step="search"
                  >
                    {isLoading ? (
                      <>
                        <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />
                        Searching...
                      </>
                    ) : (
                      <>
                        <Search className="mr-1.5 h-3.5 w-3.5" />
                        {many && pickedTowns.length > 0 ? `Find leads in ${press.run.length} town${press.run.length === 1 ? '' : 's'}` : 'Find Leads'}
                      </>
                    )}
                  </Button>
                  {isLoading && (
                    <p className="text-[10px] sm:text-xs text-muted-foreground/60 mt-1.5 text-center sm:text-right">
                      This can take 20-30 seconds - hang tight!
                    </p>
                  )}
                </>
              )}
            </div>
          </div>
        </form>
      </CardContent>
    </Card>
  );
}
